#include <iostream>
#include <cstring>
#include <algorithm>

using namespace std;

using LL = long long;

const LL MOD = 1000000007;

LL pas[101][101];
LL pd[101][1001];
int n, k;
LL m;

LL func(int i) {
    LL ret = m / n;
    if (i < m % n) ret++;
    return ret;
}

LL bigMod(LL x, LL exponent) {
    LL result = 1;
    x %= MOD;

    while (exponent > 0) {
        if (exponent & 1LL) result = result * x % MOD;
        x = x * x % MOD;
        exponent >>= 1LL;
    }

    return result;
}

LL solve(int x, int remaining) {
    if (x == n) return remaining == 0;

    LL &answer = pd[x][remaining];
    if (answer != -1) return answer;

    answer = 0;
    int limit = min(remaining, n);

    for (int i = 0; i <= limit; i++) {
        LL coefficient = bigMod(pas[n][i], func(x));
        LL value = coefficient * solve(x + 1, remaining - i) % MOD;
        answer = (answer + value) % MOD;
    }

    return answer;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    cin >> n >> m >> k;

    pas[0][0] = 1;
    for (int i = 1; i <= 100; i++) {
        pas[i][0] = pas[i][i] = 1;
        for (int j = 1; j < i; j++) {
            pas[i][j] = (pas[i - 1][j] + pas[i - 1][j - 1]) % MOD;
        }
    }

    memset(pd, -1, sizeof(pd));

    cout << solve(0, k) << '\n';
    return 0;
}

