#include <iostream>
#include <vector>
#include <algorithm>

using namespace std;

using LL = long long;

const LL MOD = 1000000007LL;

LL modPow(LL base, LL exponent) {
    LL result = 1;
    base %= MOD;

    while (exponent > 0) {
        if (exponent & 1LL) {
            result = result * base % MOD;
        }
        base = base * base % MOD;
        exponent >>= 1LL;
    }

    return result;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, k;
    LL m;
    cin >> n >> m >> k;

    if (n == 0) {
        cout << (k == 0 ? 1 : 0) << '\n';
        return 0;
    }

    vector<LL> pas(k + 1, 0);
    pas[0] = 1;
    if (k >= 1) pas[1] = 1;

    for (int i = 2; i <= n; ++i) {
        vector<LL> current(k + 1, 0);
        current[0] = 1;
        if (i <= k) current[i] = 1;

        for (int j = 1; j < i && j <= k; ++j) {
            current[j] = (pas[j] + current[j - 1]) % MOD;
        }

        pas.swap(current);
    }

    vector<LL> next(k + 1, 0), current(k + 1, 0);
    next[0] = 1;

    for (int x = n - 1; x >= 0; --x) {
        LL exponent = m / n + (x < m % n ? 1 : 0);
        vector<LL> power(k + 1, 1);

        for (int i = 1; i <= k; ++i) {
            power[i] = modPow(pas[i], exponent);
        }

        fill(current.begin(), current.end(), 0);

        for (int remaining = 0; remaining <= k; ++remaining) {
            for (int i = 0; i <= remaining; ++i) {
                current[remaining] =
                    (current[remaining] + power[i] * next[remaining - i]) % MOD;
            }
        }

        current.swap(next);
    }

    cout << next[k] << '\n';
    return 0;
}

#include <iostream>
#include <cstring>
#include <algorithm>

using namespace std;

using LL = long long;

const LL MOD = 1000000007;

LL pas[101][101];
LL pd[101][1001];
int n, k;
LL m;

LL func(int i) {
    LL ret = m / n;
    if (i < m % n) ++ret;
    return ret;
}

LL bigMod(LL x, LL exponent) {
    if (exponent == 0) return 1;
    LL res = bigMod(x, exponent / 2);
    res = (res * res) % MOD;
    if (exponent % 2 == 1) res = (res * x) % MOD;
    return res;
}

LL solve(int x, int remaining) {
    if (x == n) return remaining == 0 ? 1 : 0;

    if (pd[x][remaining] != -1) return pd[x][remaining];

    LL ret = 0;
    int limit = min(remaining, n);

    for (int i = 0; i <= limit; ++i) {
        LL res = solve(x + 1, remaining - i);

        if (i != 0) {
            res = (res * bigMod(pas[n][i], func(x))) % MOD;
        }

        ret = (ret + res) % MOD;
    }

    return pd[x][remaining] = ret;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    cin >> n >> m >> k;

    pas[0][0] = 1;
    for (int i = 1; i <= n; ++i) {
        pas[i][0] = pas[i][i] = 1;
        for (int j = 1; j < i; ++j) {
            pas[i][j] = (pas[i - 1][j] + pas[i - 1][j - 1]) % MOD;
        }
    }

    memset(pd, -1, sizeof(pd));

    cout << solve(0, k) << '\n';
    return 0;
}

